SELECT "gsoffered" AS grade_span
FROM schools
WHERE "longitude" = (SELECT MAX("longitude") FROM schools);

355:
SELECT DISTINCT c."keywords"
FROM "cards" c
WHERE LOWER(TRIM(c."name")) = LOWER(TRIM('Angel of Mercy'));

509:
SELECT "id"
FROM "sets"
WHERE "basesetsize" = (SELECT MAX(CAST("basesetsize" AS BIGINT)) FROM "sets");

588:
SELECT COUNT(*) AS total_comments
FROM "comments" c
WHERE c."userid" = 13;

747:
SELECT COUNT(*) AS total_superheroes_without_full_name
FROM "superhero"
WHERE "full_name" IS NULL;

1377:
SELECT COUNT(DISTINCT m."member_id") AS president_count
FROM "member" m
WHERE LOWER(TRIM(m."position")) = LOWER('President');
